import{createStoryFlow,flowParams,flowCommands,flowOrder,insertFlowStep,removeFlowStep,swapFlowSteps,validateStoryFlow,previewStoryFlow}from'./story-flow.js';
import{readableStoryAction}from'./story-readable.js';
import{mountMovementPathEditor}from'./scene-map-ui.js';
import{SCRIPT_DATA}from'./script-data.js';
import{nativeStateChoices,nameStoryState,insertStoryCondition}from'./native-story-state.js';
const BASE=0x08000000,hex=n=>'0x'+n.toString(16).toUpperCase();
export function openStoryFlow({api,graph,root,session,afterSave,selected=null}){
 const $=s=>document.querySelector(s),esc=api.esc;let flow=structuredClone(graph.edits.flows?.[root.id]??createStoryFlow(graph,root)),history=[],future=[],active=selected&&flow.nodes[selected]?selected:flow.entry,filter='',category='all',applyCurrent=()=>{};
 const defs=new Map(SCRIPT_DATA[graph.engine].map(c=>[c.code,c])),catalog=flowCommands(graph.engine),actions=()=>flowOrder(flow),label=n=>n.sourceAt===undefined?defs.get(n.code)?.name:graph.nodes[n.sourceAt]?.adapter?.name||graph.nodes[n.sourceAt]?.name;
 const group=c=>/message|buffer|text|button|multichoice|yesno/.test(c.name)?'Dialogue and choices':/movement|object|face|lock|release/.test(c.name)?'Characters and movement':/battle|trainer|mon|party/.test(c.name)?'Battles and Pokémon':/flag|var|compare|goto|call|end|return/.test(c.name)?'Branches and progress':/item|money|coin|decor/.test(c.name)?'Items and money':/music|bgm|se$|fanfare|cry|sound/.test(c.name)?'Music and sound':/warp|weather|metatile|door|map|screen|flash/.test(c.name)?'Map and screen':'Other commands';
 function message(e){$('#flowError').textContent=e.message;}
 function conditionBuilder(rows,n,stepTitle){
  return `<details id="flowConditionPanel"><summary>Add a guided condition</summary><p>Check existing saved game state, then choose what happens in each branch. This uses the same event steps as advanced editing.</p><label>Check<select id="flowConditionKind"><option value="flag">Progress flag</option><option value="variable">Story value</option></select></label><label>Existing ROM state<select id="flowConditionState"></select></label><label>Readable name<input id="flowConditionName" maxlength="80" placeholder="e.g. Has the gate key"></label><button type="button" id="flowConditionNameSave">Save state name</button><p class="hint-line">Names are project notes, not new native IDs. Import the entire ROM to discover more existing state. New IDs are not guessed.</p><label>Condition<select id="flowConditionOperator"></select></label><label id="flowConditionValueLabel" hidden>Compare with<input id="flowConditionValue" type="number" min="0" max="65535" value="1"></label>${[['True','Condition matches'],['False','Otherwise']].map(([key,title])=>`<fieldset><legend>${title}</legend><label>Optional dialogue<textarea id="flowCondition${key}Text" rows="3" placeholder="Leave empty to continue directly"></textarea></label><label>Then continue at<select id="flowCondition${key}Target">${rows.map((r,i)=>`<option value="${r.id}" ${r.id===n.id?'selected':''}>${i+1}. ${esc(stepTitle(r))}</option>`).join('')}</select></label></fieldset>`).join('')}<button type="button" id="flowConditionInsert">Add condition before this step</button><p class="hint-line">Dialogue waits for a button and closes before continuing. Branches rejoin the chosen step, without replaying the condition.</p></details>`;
 }
 function bindConditionBuilder(){
  const kind=()=>$('#flowConditionKind').value;
  const nameField=()=>{const key=kind()==='flag'?'flags':'variables';$('#flowConditionName').value=graph.symbols?.[key]?.[$('#flowConditionState').value]||'';};
  const choices=()=>{const previous=$('#flowConditionState').value,rows=nativeStateChoices(graph,kind());$('#flowConditionState').innerHTML=rows.map(r=>`<option value="${r.id}">${esc(r.label)} · ${hex(r.id)}</option>`).join('')||'<option value="">No indexed state of this type</option>';if(rows.some(r=>String(r.id)===previous))$('#flowConditionState').value=previous;$('#flowConditionInsert').disabled=!rows.length;$('#flowConditionNameSave').disabled=!rows.length;nameField();};
  const refresh=()=>{const flag=kind()==='flag';$('#flowConditionOperator').innerHTML=(flag?[['eq','Is set / complete'],['ne','Is not set']]:[['eq','Equals'],['ne','Does not equal'],['lt','Less than'],['lte','At most'],['gt','Greater than'],['gte','At least']]).map(([v,t])=>`<option value="${v}">${t}</option>`).join('');$('#flowConditionValueLabel').hidden=flag;choices();};
  $('#flowConditionKind').onchange=refresh;$('#flowConditionState').onchange=nameField;
  $('#flowConditionNameSave').onclick=()=>{try{const value=$('#flowConditionState').value;if(!value)throw Error('Choose an indexed native state.');api.change(()=>nameStoryState(graph,kind(),Number(value),$('#flowConditionName').value));choices();api.toast('State name saved in this project. ROM IDs are unchanged.');}catch(e){message(e);}};
  $('#flowConditionInsert').onclick=()=>mutate(()=>{const value=$('#flowConditionState').value;if(!value)throw Error('Choose an indexed native state.');active=insertStoryCondition(flow,active,graph.engine,{kind:kind(),id:Number(value),operator:$('#flowConditionOperator').value,value:Number($('#flowConditionValue').value),trueText:$('#flowConditionTrueText').value,falseText:$('#flowConditionFalseText').value,whenTrue:$('#flowConditionTrueTarget').value,whenFalse:$('#flowConditionFalseTarget').value}).entry;});
  refresh();
 }
 function mutate(fn){const prior=structuredClone(flow);try{applyCurrent();fn();validateStoryFlow(flow,graph,root);history.push(prior);future=[];draw();}catch(e){flow=prior;draw();message(e);}}
 function discard(){api.change(()=>{if(graph.edits.flows)delete graph.edits.flows[root.id];});api.close();afterSave();}
 api.modal('Arrange event · '+root.title,`<p>Changes here apply to this event entry. Its branches and sub-events are kept linked; other entries retain their original structure. Linked dialogue and movement edits made elsewhere still apply unless replaced here.</p><div class="smart-actions"><button type="button" id="flowUndo">Undo draft</button><button type="button" id="flowRedo">Redo draft</button><button type="button" id="flowRestore">Restore original structure</button></div><p id="flowError" role="alert" class="danger"></p><div class="flow-editor"><section><label>Find an event step<input type="search" id="flowSearch" placeholder="Dialogue, battle, flag, character…"></label><div id="flowList" class="flow-list"></div></section><section id="flowDetails"></section></div>`,()=>{applyCurrent();validateStoryFlow(flow,graph,root);api.change(()=>{graph.edits.flows??={};graph.edits.flows[root.id]=structuredClone(flow);});afterSave();},'Save event structure');
 const editor=document.querySelector('.flow-editor'),tabs=document.createElement('nav');tabs.className='flow-mobile-tabs';tabs.setAttribute('aria-label','Event structure editor');tabs.innerHTML='<button type="button" id="flowShowSteps">Event steps</button><button type="button" id="flowShowDetails">Edit selected step</button>';editor.before(tabs);
 const pane=value=>{editor.dataset.mobilePane=value;$('#flowShowSteps').setAttribute('aria-pressed',String(value==='steps'));$('#flowShowDetails').setAttribute('aria-pressed',String(value==='details'));};pane('steps');$('#flowShowSteps').onclick=()=>pane('steps');$('#flowShowDetails').onclick=()=>pane('details');
 const quick=document.createElement('button');quick.type='button';quick.id='flowConditionQuick';quick.textContent='Add condition / branch';$('#flowRestore').before(quick);quick.onclick=()=>{pane('details');const panel=$('#flowConditionPanel');panel.open=true;panel.scrollIntoView({block:'start',behavior:'smooth'});};
 $('#flowUndo').onclick=()=>{if(history.length){future.push(structuredClone(flow));flow=history.pop();draw();}};$('#flowRedo').onclick=()=>{if(future.length){history.push(structuredClone(flow));flow=future.pop();draw();}};$('#flowRestore').onclick=discard;$('#flowSearch').oninput=()=>{filter=$('#flowSearch').value.toLowerCase();draw();};
 function draw(){const rows=actions(),preview=previewStoryFlow(graph,root,flow),byId=new Map(Object.values(preview.nodes).map(n=>[n.flowStep,n]));if(!flow.nodes[active])active=flow.entry;$('#flowError').textContent='';$('#flowUndo').disabled=!history.length;$('#flowRedo').disabled=!future.length;$('#flowList').innerHTML=rows.filter(n=>!filter||[label(n),readableStoryAction(preview,byId.get(n.id)).detail].join(' ').toLowerCase().includes(filter)).map(n=>{const a=readableStoryAction(preview,byId.get(n.id));return`<button type="button" data-flow-select="${n.id}" aria-pressed="${active===n.id}"><small>${rows.indexOf(n)+1} · ${n.sourceAt===undefined?'Added':'Imported'}${flow.entry===n.id?' · Start':''}</small><b>${esc(a.title)}</b><span>${esc(a.detail.slice(0,100))}</span></button>`;}).join('');for(const b of document.querySelectorAll('[data-flow-select]'))b.onclick=()=>{const prior=structuredClone(flow);try{applyCurrent();validateStoryFlow(flow,graph,root);if(JSON.stringify(prior.nodes[active])!==JSON.stringify(flow.nodes[active])){history.push(prior);future=[];}active=b.dataset.flowSelect;pane('details');draw();}catch(e){flow=prior;draw();message(e);}};details(rows,byId,preview);}
 function details(rows,byId,view){const stepTitle=row=>{const a=readableStoryAction(view,byId.get(row.id));return a.title+(a.detail?' · '+a.detail.replace(/\s+/g,' ').slice(0,45):'');};
  const n=flow.nodes[active],source=graph.nodes[n.sourceAt],def=defs.get(n.code),params=source?.args??flowParams(graph.engine,n)??[],options=(selected,empty=false)=>(empty?'<option value="">None</option>':'')+rows.map((r,i)=>`<option value="${r.id}" ${r.id===selected?'selected':''}>${i+1}. ${esc(stepTitle(r))}</option>`).join('');
  $('#flowDetails').innerHTML=`<h3>${esc(readableStoryAction(previewStoryFlow(graph,root,flow),byId.get(n.id)).title)}</h3><p class="hint-line">${esc(label(n))}${source?.opaque?' · unresolved bytes stay in the original ROM':''}</p><div class="smart-actions"><button type="button" id="flowRemove" ${!n.next?'disabled':''}>Delete step</button><button type="button" id="flowSwap">Move after next step</button></div><div id="flowFields">${params.map((p,i)=>{if(n.targets[i]!==undefined)return`<label>${esc(p.name)}<select data-flow-target="${i}">${options(n.targets[i])}</select></label>`;if(p.width===4&&(p.kind==='text'||p.kind==='movement'||[79,80,103,133,155].includes(n.code))){const kind=p.kind??([79,80].includes(n.code)?'movement':'text'),old=graph[kind==='text'?'texts':'movements'][n.args[i]-BASE],data=n.data[i]??(old&&(kind==='text'?{kind,text:graph.edits.texts[old.at]?.text??old.text}:{kind,bytes:graph.edits.movements[old.at]?.bytes??old.bytes}));if(kind==='text')return`<label>${esc(p.name)}<textarea rows="5" data-flow-text="${i}">${esc(data?.text??'')}</textarea></label><p class="hint-line">\\p starts a page, \\n starts the second line, \\l scrolls. This text is local to this event.</p>`;return`<label>${esc(p.name)} · movement actions<input data-flow-movement="${i}" value="${(data?.bytes??[254]).slice(0,-1).join(', ')}"></label><button type="button" data-flow-draw="${i}">Draw route on map</button><details><summary>Movement action names</summary><p>${Object.entries(SCRIPT_DATA.movements).map(([name,code])=>esc(name)+' = '+code).join(' · ')}</p></details><div id="flowDrawing${i}"></div>`;}
   return`<label>${esc(p.name)}<input data-flow-number="${i}" value="${hex(n.args[i])}" ${p.kind==='native'||n.code===92&&i===0?'readonly':''}></label>`;}).join('')}</div>${n.next?`<label>Continue at<select id="flowNext">${options(n.next)}</select></label>`:''}<button type="button" id="flowApply" ${source?.opaque?'disabled':''}>Apply step changes</button><hr>${conditionBuilder(rows,n,stepTitle)}<hr><h3>Add before this step</h3><label>Command group<select id="flowGroup"><option value="all">All commands</option>${[...new Set(catalog.map(group))].sort().map(x=>`<option>${esc(x)}</option>`).join('')}</select></label><label>Action<select id="flowAddCommand"></select></label><button type="button" id="flowAdd">Add action</button><button type="button" id="flowAddDialogue">Add dialogue with wait and close</button><p class="hint-line">Commands use this ROM’s native IDs and rules. Custom engine functions remain preserved unless their adapter verifies editable inputs. Step numbers are navigation labels; branches determine execution order.</p>`;
  bindConditionBuilder();$('#flowRemove').onclick=()=>mutate(()=>removeFlowStep(flow,active));$('#flowSwap').onclick=()=>mutate(()=>swapFlowSteps(flow,active));
  const fillCatalog=()=>{$('#flowAddCommand').innerHTML=catalog.filter(c=>category==='all'||group(c)===category).map(c=>`<option value="${c.code}">${esc(readableStoryAction({texts:{},edits:{commands:{},texts:{}}},{name:c.name,code:c.code,args:c.params.map(p=>({...p,value:0}))}).title)} (${esc(c.name)})</option>`).join('');};$('#flowGroup').value=category;$('#flowGroup').onchange=()=>{category=$('#flowGroup').value;fillCatalog();};fillCatalog();
  $('#flowAdd').onclick=()=>mutate(()=>{const c=catalog.find(c=>c.code===+$('#flowAddCommand').value),data={};c.params.forEach((p,i)=>{if(p.width===4&&[79,80].includes(c.code))data[i]={kind:'movement',bytes:[254]};if(p.width===4&&([103,133,155].includes(c.code)||p.kind==='text'))data[i]={kind:'text',text:''};});active=insertFlowStep(flow,active,c,{data}).id;});
  $('#flowAddDialogue').onclick=()=>mutate(()=>{const before=active;let anchor=before;for(const name of['closemessage','waitbuttonpress','waitmessage','message']){const c=catalog.find(c=>c.name===name),row=insertFlowStep(flow,anchor,c,{data:name==='message'?{0:{kind:'text',text:''}}:{}});anchor=row.id;}active=anchor;});
  applyCurrent=()=>{if(source?.opaque)return;for(const input of document.querySelectorAll('[data-flow-number]')){const i=+input.dataset.flowNumber,s=input.value.trim();if(!/^(0x[0-9a-f]+|\d+)$/i.test(s))throw Error('Use a number or 0x hexadecimal value.');n.args[i]=Number(s);}for(const input of document.querySelectorAll('[data-flow-target]'))n.targets[input.dataset.flowTarget]=input.value;for(const input of document.querySelectorAll('[data-flow-text]'))n.data[input.dataset.flowText]={kind:'text',text:input.value};for(const input of document.querySelectorAll('[data-flow-movement]')){const s=input.value.trim(),bytes=s?s.split(/[\s,]+/).map(Number):[];n.data[input.dataset.flowMovement]={kind:'movement',bytes:[...bytes,254]};}if($('#flowNext'))n.next=$('#flowNext').value;};$('#flowApply').onclick=()=>mutate(applyCurrent);
  for(const b of document.querySelectorAll('[data-flow-draw]'))b.onclick=()=>{const i=b.dataset.flowDraw,preview=previewStoryFlow(graph,root,flow),previewRoot=preview.roots.find(r=>r.id===root.id),node=Object.values(preview.nodes).find(x=>x.flowStep===n.id);$('#flowDrawing'+i).replaceChildren(mountMovementPathEditor({api,graph:preview,root:previewRoot,session,node,onApply:bytes=>{const input=document.querySelector('[data-flow-movement="'+i+'"]');input.value=bytes.join(', ');api.toast('Route added to this step draft. Apply step changes, then save the event.');}}));};
 }
 draw();
}
